                        result = D2DAlignToStr(l_AD.MenuAlign);
                    }
                }
            }
            if (result == Null)
            {
                if (AnsiSameText(aName, c_MouseX))
                {
                    result = gD2DE.MouseX;
                }
                else
                {
                    if (AnsiSameText(aName, c_MouseY))
                    {
                        result = gD2DE.MouseY;
                    }
                    else
                    {
                        if (AnsiSameText(aName, c_BMenuAlign))
                        {
                            result = D2DAlignToStr(f_BtnMenuAlign);
                        }
                        else
                        {
                            if (AnsiSameText(aName, c_LMenuAlign))
                            {
                                result = D2DAlignToStr(f_LinkMenuAlign);
                            }
                        }
                    }
                }
            }
            if ((result == Null) & AnsiSameText(aName, c_FullScreen))
            {
                result = BoolToVar(~gD2DE.Windowed);
            }
            if ((result == Null) & AnsiSameText(aName, c_IsMusic))
            {
                result = BoolToVar(gD2DE.Music_IsPlaying);
            }
            if ((result == Null) & AnsiStartsText(cs_GSS_, aName))
            {
                l_DName = Copy(aName, 5, MaxInt);
                result = f_SettingsStorage[l_DName];
            }
        }
        return result;
    }
    
