    private bool ParseDecorVar(in string aVarName, ref string theDName, ref string theDVarName)
    {
        string l_VN;
        int l_Pos;
        string l_DN;
        bool result;
    
        result = false;
        if (AnsiStartsText(cs_Decor_, aVarName))
        {
            l_VN = Copy(aVarName, 7, MaxInt);
            if (Pos("_", l_VN) > 0)
            {
                l_Pos = Length(l_VN);
                while (l_VN[l_Pos] != "_")
                {
                    Dec(l_Pos);
                }
                l_DN = Copy(l_VN, 1, (l_Pos - 1));
                Delete(l_VN, 1, l_Pos);
                if ((l_DN != "") & (l_VN != ""))
                {
                    theDName = l_DN;
                    theDVarName = l_VN;
                    result = true;
                }
            }
        }
        return result;
    }
    
    protected override IFURQActionData pm_GetActionsData(string anID)
    {
        int I;
        If2ActionDecorator l_AC;
        IFURQActionData result;
    
        result = pm_GetActionsData;
        if (result == null)
        {
            for (I = 0; I <= (f_Decorators.Count - 1); I++)
            {
                l_AC = f_Decorators.Decorators[I].AsActionDecorator;
                if (l_AC != null)
                {
                    result = l_AC.GetActionsData(anID);
                    if (result != null)
                    {
                        break;
                    }
                }
            }
        }
        return result;
    }
    
