    protected override bool SetVirtualVariables(in string aName, in Variant aValue)
    {
        If2ActionDecorator l_AD;
        string l_DName = default!;
        string l_DVar = default!;
        Tf2BaseDecorator l_Decor;
        Td2dTextAlignType l_Align;
        If2TargetProvider l_TP = default!;
        bool result;
    
        result = SetVirtualVariables;
        if (!result)
        {
            if (ParseDecorVar(aName, l_DName, l_DVar))
            {
                l_Decor = GetDecorator(l_DName);
                if (l_Decor != null)
                {
                    result = true;
                    l_DVar = AnsiUpperCase(l_DVar);
                    if (l_DVar == "X")
                    {
                        l_Decor.PosX = global::furqTypesModule.EnsureReal(aValue);
                    }
                    else
                    {
                        if (l_DVar == "Y")
                        {
                            l_Decor.PosY = global::furqTypesModule.EnsureReal(aValue);
                        }
                        else
                        {
                            if (l_DVar == "Z")
                            {
                                l_Decor.PosZ = global::furqTypesModule.EnsureReal(aValue);
                            }
                            else
                            {
                                if ((l_DVar == cs_COLOR) & (l_Decor is Tf2ColoredDecorator))
                                {
                                    ((Tf2ColoredDecorator)(l_Decor)).Color = CorrectColor(aValue);
                                }
                                else
                                {
                                    if (l_DVar == cs_HIDE)
                                    {
                                        l_Decor.Visible = (aValue == 0);
                                    }
                                    else
                                    {
                                        if (l_DVar == cs_SCRIPT)
                                        {
                                            l_Decor.Script = CompileDSOperators(aValue);
                                        }
                                        else
                                        {
                                            result = false;
                                        }
                                    }
                                }
                            }
                        }
                    }
                    if (!result & (l_Decor is Tf2TextDecorator))
                    {
                        result = true;
                        if (l_DVar == cs_TEXT)
                        {
                            ((Tf2TextDecorator)(l_Decor)).Text = EnsureString(aValue);
                        }
                        else
                        {
                            if (l_DVar == cs_WIDTH)
                            {
                                ((Tf2TextDecorator)(l_Decor)).Width = aValue;
                            }
                            else
                            {
                                if (l_DVar == cs_ALIGN)
                                {
                                    l_Align = ((Tf2TextDecorator)(l_Decor)).Align;
                                    VariantToAlign(aValue, l_Align);
                                    ((Tf2TextDecorator)(l_Decor)).Align = l_Align;
                                }
                                else
                                {
                                    if (l_DVar == cs_LINESPACING)
                                    {
                                        ((Tf2TextDecorator)(l_Decor)).LineSpacing = aValue;
                                    }
                                    else
                                    {
                                        if (l_DVar == cs_PARASPACING)
                                        {
                                            ((Tf2TextDecorator)(l_Decor)).ParaSpacing = aValue;
                                        }
                                        else
                                        {
                                            if (l_DVar == cs_LINKCOLOR)
                                            {
                                                ((Tf2TextDecorator)(l_Decor)).LinkColor = CorrectColor(aValue);
                                            }
                                            else
                                            {
                                                if (l_DVar == cs_LINKHCOLOR)
                                                {
                                                    ((Tf2TextDecorator)(l_Decor)).LinkHColor = CorrectColor(aValue);
                                                }
                                                else
                                                {
                                                    result = false;
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    if (!result & (l_Decor is Tf2GraphicDecorator))
                    {
                        result = true;
                        if (l_DVar == cs_HOTX)
                        {
                            ((Tf2GraphicDecorator)(l_Decor)).HotX = aValue;
                        }
                        else
                        {
                            if (l_DVar == cs_HOTY)
                            {
                                ((Tf2GraphicDecorator)(l_Decor)).HotY = aValue;
                            }
                            else
                            {
                                if (l_DVar == cs_ANGLE)
                                {
                                    ((Tf2GraphicDecorator)(l_Decor)).Angle = aValue;
                                }
                                else
                                {
                                    if (l_DVar == cs_ROTSPEED)
                                    {
                                        ((Tf2GraphicDecorator)(l_Decor)).RotSpeed = aValue;
                                    }
                                    else
                                    {
                                        if (l_DVar == cs_SCALE)
                                        {
                                            ((Tf2GraphicDecorator)(l_Decor)).Scale = aValue;
                                        }
                                        else
                                        {
                                            result = false;
                                        }
                                    }
                                }
                            }
                        }
                    }
                    if (!result & (l_Decor is Tf2BasicSpriteDecorator))
                    {
                        result = true;
                        if (l_DVar == cs_FLIPX)
                        {
                            ((Tf2BasicSpriteDecorator)(l_Decor)).FlipX = (aValue != 0.0);
                        }
                        else
                        {
                            if (l_DVar == cs_FLIPY)
                            {
                                ((Tf2BasicSpriteDecorator)(l_Decor)).FlipY = (aValue != 0.0);
                            }
                            else
                            {
                                result = false;
                            }
                        }
                    }
                    if (!result & (l_Decor is Tf2AnimationDecorator))
                    {
                        result = true;
                        if (l_DVar == cs_FRAME)
                        {
                            ((Tf2AnimationDecorator)(l_Decor)).CurFrame = aValue;
                        }
                        else
                        {
                            if (l_DVar == cs_ANISPEED)
                            {
                                ((Tf2AnimationDecorator)(l_Decor)).Speed = aValue;
                            }
                            else
                            {
                                if (l_DVar == cs_ANITYPE)
                                {
                                    ((Tf2AnimationDecorator)(l_Decor)).AniType = aValue;
                                }
                                else
                                {
                                    result = false;
                                }
                            }
                        }
                    }
                    if (!result & (l_Decor is Tf2GIFDecorator))
                    {
                        result = true;
                        if (l_DVar == cs_FRAME)
                        {
                            ((Tf2GIFDecorator)(l_Decor)).Frame = aValue;
                        }
                        else
                        {
                            if (l_DVar == cs_ANISPEED)
                            {
                                ((Tf2GIFDecorator)(l_Decor)).AniSpeed = aValue;
                            }
                            else
                            {
                                result = false;
                            }
                        }
                    }
                    if (!result & (l_Decor is Tf2TextButtonDecorator))
                    {
                        result = true;
                        if (l_DVar == cs_TEXT)
                        {
                            ((Tf2TextButtonDecorator)(l_Decor)).Text = aValue;
                        }
                        else
                        {
                            if (l_DVar == cs_WIDTH)
                            {
                                ((Tf2TextButtonDecorator)(l_Decor)).Width = aValue;
                            }
                            else
                            {
                                if (l_DVar == cs_ALIGN)
                                {
                                    ((Tf2TextButtonDecorator)(l_Decor)).TextAlign = IntToAlign(aValue);
                                }
                                else
                                {
                                    result = false;
                                }
                            }
                        }
                    }
                    if (!result & (l_DVar == cs_ENABLED))
                    {
                        result = true;
                        l_AD = l_Decor.AsActionDecorator;
                        if (l_AD != null)
                        {
                            l_AD.Enabled = (aValue != 0.0);
                        }
                    }
                    if (!result & (l_DVar == cs_MENUALIGN))
                    {
                        result = true;
                        l_AD = l_Decor.AsActionDecorator;
                        if (l_AD != null)
                        {
                            l_AD.MenuAlign = D2DStrToAlign(EnsureString(aValue));
                        }
                    }
                    if (!result & Supports(l_Decor, If2TargetProvider, l_TP))
                    {
                        result = true;
                        if (l_DVar == cs_TARGET)
                        {
                            l_TP.GetTargetProcessor.Target = EnsureString(aValue);
                        }
                        else
                        {
                            result = false;
                        }
                    }
                }
            }
            if (!result & AnsiSameText(aName, c_FullScreen))
            {
                gD2DE.Windowed = (aValue == 0);
                Variables[cs_gss_fullscreen] = aValue;
                result = true;
            }
            if (!result & AnsiSameText(aName, c_BMenuAlign))
            {
                f_BtnMenuAlign = D2DStrToAlign(EnsureString(aValue));
                result = true;
            }
            if (!result & AnsiSameText(aName, c_LMenuAlign))
            {
                f_LinkMenuAlign = D2DStrToAlign(EnsureString(aValue));
                result = true;
            }
            if (!result & AnsiStartsText(cs_GSS_, aName))
            {
                l_DName = Copy(aName, 5, maxInt);
                if (l_DName != "")
                {
                    f_SettingsStorage[l_DName] = aValue;
                }
                result = true;
            }
            if (!result)
            {
                result = (AnsiSameText(aName, c_MouseX) | AnsiSameText(aName, c_MouseY));
            }
        }
        return result;
    }
    
