    public override bool SystemProc(string aProcName, IJclStringList aParams)
    {
        int I;
        Variant l_Col;
        bool result = default!;
    
        if (AnsiSameText(aProcName, cs__color) & (aParams.Count > 2))
        {
            for (I = 0; I <= Pred(aParams.Count); I++)
            {
                aParams.Variants[I] = (aParams.Variants[I] % 256);
            }
            if (aParams.Count == 3)
            {
                l_Col = ARGB(0xFF, aParams.Variants[0], aParams.Variants[1], aParams.Variants[2]);
            }
            else
            {
                l_Col = ARGB(aParams.Variants[0], aParams.Variants[1], aParams.Variants[2], aParams.Variants[3]);
            }
            Variables[cs__result] = VarAsType(l_Col, varDouble);
            result = true;
        }
        if (!result)
        {
            result = SystemProc;
        }
        return result;
    }
    
    public void VoicePlay(in string aFilename)
    {
        VoiceStop();
        f_VoiceFilename = aFilename;
        gD2DE.Snd_PlaySample(aFilename, Variables[c_VoiceVolume]);
    }
    
    public void VoiceStop()
    {
        if (f_VoiceFilename != "")
        {
            gD2DE.Snd_FreeSample(f_VoiceFilename);
            f_VoiceFilename = "";
        }
    }
    
}

